  insert into public.brands (name, website, description, country, status) values ('ELASCO Skincare', 'https://elascoskincare.com/', 'ELASCO is a high-performance skincare brand focused on skin longevity, selling products including the RE-HYDRA Serum, MAGI-C Serum (20% vitamin C), Resc-U Spray and Re-Juvenate Elixir. Its homepage says it began with Mukhtar Siddiqui, an organic chemist with four decades formulating skincare, and Linda Lin, its Co-Founder & CEO. Its TYR (Thank You Reward) program pays sharers 25% on every sale made through their link.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
