  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Become an ELASCAN — TYR Program (Thank You Reward)', 'https://elascoskincare.com/pages/become-an-elascan', 'https://elascoskincare.com/pages/become-an-elascan', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://elascoskincare.com/pages/become-an-elascan', 'official_site', 'affiliate', 'TYR Program pays 25% on every sale through the affiliate''s link, plus 5% for life on sales by ambassadors they bring in; uncapped wording verbatim: ''Every time someone buys through it, 25% comes back to you — no cap, no fees, no limit.'' and ''Real rewards on every purchase through your link — no cap, no hidden fees.'' Page says most applications are reviewed and approved within 1 business day.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://elascoskincare.com/', 'official_site', 'general', 'Homepage describes ELASCO as ''High-Performance Care for Skin Longevity'', founded on chemistry by Mukhtar Siddiqui and CEO Linda Lin, with serums, makeup remover, spray and elixir products listed with prices.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 15, 19, 8, 9, 4, '{"niche_fit": "Pure indie skincare brand built entirely around serums and skin longevity, a direct fit for skincare creators.", "ugc_evidence": "Program page tells members to share by text, email, social or blog and provides ready-made images, captions and product facts.", "compensation": "Published 25% on every sale plus 5% lifetime network reward, with explicit ''no cap, no fees, no limit'' wording.", "contact_access": "No email was published on the fetched page; access is only via the on-page application form and ELASCAN portal.", "opportunity_availability": "Applications are open on the page and the brand says most are approved within 1 business day.", "credibility": "Named founders and a disclosed 30-day participant survey (n=16) on the homepage support credibility."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('CA Perfume Club', 'https://caperfume.com/pages/brand-ambassadors', 'CA Perfume Club is a California fragrance brand that publishes a HumanSafe ingredient-transparency framework disclosing every ingredient and a MEi Mood Architecture framework mapping scents to moods. Ambassadors receive a complimentary 1.7 fl oz fragrance and create video reviews and UGC content.', 'United States', 'published') returning id into bid;
