  insert into public.brands (name, website, description, country, status) values ('Amal', 'https://pureamal.com/', 'Amal makes handcrafted small-batch Sudanese makhmaria, a solid fragrance/body balm crafted with 100% natural shea butter, oud, rose and botanical oils. The brand presents itself as Sudanese luxury natural cosmetics rooted in centuries-old heritage recipes passed from mother to daughter.', null, 'published') returning id into bid;
