  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 18, 10, 9, 4, '{"niche_fit": "Indie small-batch fragrance/body makhmaria fits the fragrance and body-care scope directly.", "ugc_evidence": "Page invites beauty influencers and creators to share links on social media and blogs, but does not describe a formal UGC package.", "compensation": "Published 15% rate plus verbatim uncapped wording and weekly payouts.", "contact_access": "Public application on the affiliate page with WhatsApp contact mentioned, but no email was published on the fetched page.", "opportunity_availability": "Applications are open and stated to be reviewed within 48 hours.", "credibility": "Official site with detailed product, heritage and program terms published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Watts Beauty USA', 'https://www.wattsbeautyusa.com/', 'Watts Beauty is a clean beauty skincare brand operating since 2005, selling serums, creams and related skin and hair products. Its affiliate page says its mission celebrates the beauty of every woman and supports programs and shelters for domestic violence survivors. Affiliates earn cash commission on referred orders and reorders through personalized links.', null, 'published') returning id into bid;
