  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Become an Affiliate (Earn Cash) — Watts Beauty Affiliate Program', 'https://www.wattsbeautyusa.com/pages/share-and-earn-cash', 'https://www.wattsbeautyusa.com/pages/share-and-earn-cash', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wattsbeautyusa.com/pages/share-and-earn-cash', 'official_site', 'affiliate', 'Affiliate option pays 15%-30% commission on every referred order and reorder, paid daily via PayPal or store credit, with 6-month tracking; uncapped wording verbatim: ''Affiliates can earn unlimited cash with 15%-30% commission on every referred order and reorder''. The page also states ''Unlimited referrals for unlimited rewards'' for its referrer option, and notes applicants must be a customer to sign up.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wattsbeautyusa.com/pages/share-and-earn-cash', 'official_site', 'ugc_collab', 'The on-page affiliate application asks applicants for their website(s) and Facebook, Instagram, YouTube and TikTok links, showing the program is aimed at social creators and influencers.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 18, 9, 8, 4, '{"niche_fit": "Long-running clean skincare brand whose affiliate copy specifically addresses sharing skincare with online audiences.", "ugc_evidence": "Application form collects Facebook, Instagram, YouTube and TikTok links, evidencing creator-focused recruitment.", "compensation": "Published 15%-30% commission range (15% used as the base rate) with explicit ''earn unlimited cash'' wording, though sign-up requires being a customer.", "contact_access": "No email was published on the fetched page; access is via the on-page application form only.", "opportunity_availability": "Page invites applications with ''Apply Today, Start Earning Today'' and an open application form.", "credibility": "Brand states it has operated since 2005 and redirected $563,000 per year back to customers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('SOSS', 'https://sossd.co', 'SOSS (So Organic, So Suave) is a Black-owned, founder-led men''s beard care brand founded in Los Angeles in 2020, making natural beard butter, a daily beard soufflé moisturizer, and African black soap for every beard texture. The founder personally reads every partnership submission and runs affiliate, barbershop partner, brand ambassador, and content-sharing routes through one Join Us page.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'team@sossd.co', 'https://sossd.co/pages/join-us', 'https://sossd.co/pages/faq', 'verified', now());
