  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SOSS Affiliate Program / Brand Ambassador — Join Us', 'https://sossd.co/pages/join-us', 'https://sossd.co/pages/join-us', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sossd.co/pages/join-us', 'official_site', 'affiliate', 'Official Join Us page lists an Affiliate Program: ''For creators with a real audience and real taste. Earn commission on every sale you drive with your own link and code.'' No commission rate or cap wording is published, so rate is null and cap is unknown. Founder states: ''Every submission comes straight to me'' and lists questions contact team@sossd.co.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sossd.co/pages/faq', 'official_site', 'ugc_collab', 'FAQ states the Affiliate Program ''welcomes creators of every size, from under 5K followers on up,'' is for creators on Instagram, TikTok, YouTube, podcast, blog, or newsletter, and that the founder reads each submission personally and replies by email if there is a fit — evidence of a small, founder-run program actively recruiting small/first creators (low saturation).', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 5, 14, 9, 5, '{"niche_fit": "Pure men''s beard care and grooming brand, squarely in the Group M scope.", "ugc_evidence": "Four creator routes (content sharing, affiliate, barbershop, ambassador) with featured-content reposting, explicitly open to under-5K creators.", "compensation": "Commission is promised but no rate is published anywhere on the fetched pages, so compensation is capped low per the rubric.", "contact_access": "Direct published email team@sossd.co plus a single application page read personally by the founder.", "opportunity_availability": "Join Us application is live and open to creators of every size.", "credibility": "Registered U.S. trademark (Reg. No. 5,920,708) and press features (Essence, Ebony, Vogue, GQ, Men''s Health) stated on the official FAQ."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lumity', 'https://lumitylife.com/', 'Lumity sells a clinically tested supplement and skincare range, including Skin Nutrients Facial Oil, Body Oil and a Cleansing Balm, positioned around healthy ageing and skin, hair and nail support. Its Referral Program FAQ dedicates its Ambassador Program to bloggers and influencers who produce health and beauty content. Ambassadors earn 15% commission on sales, including recurring commission while referred customers stay subscribed.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
