  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://lumitylife.com/pages/lumity-referral-program-faqs', 'https://lumitylife.com/pages/lumity-referral-program-faqs', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 15, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://lumitylife.com/pages/lumity-referral-program-faqs.', 'https://lumitylife.com/pages/lumity-referral-program-faqs', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lumity Ambassador Program — Referral Program for Bloggers and Influencers', 'https://lumitylife.com/pages/lumity-referral-program-faqs', 'https://lumitylife.com/pages/lumity-referral-program-faqs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lumitylife.com/pages/lumity-referral-program-faqs', 'official_site', 'affiliate', 'FAQ Q5: ambassadors receive 15% commission on sales (partners, who are medical professionals, receive 25%). FAQ Q6 ''How much money can I make?'' — uncapped wording verbatim: ''There''s no limit on the amount of commissions you can earn, so the more people you successfully refer to buy Lumity, the more money you''ll make.'' FAQ Q11 gives maria@lumitylife.co.uk for program questions.', 'verified', now());
