  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 15, 17, 13, 8, 4, '{"niche_fit": "Range spans supplements as well as skincare (facial oil, body oil, cleansing balm), so the skincare fit is real but partial.", "ugc_evidence": "Ambassador tier is explicitly dedicated to bloggers and influencers producing health and beauty content.", "compensation": "Published 15% ambassador commission with an explicit FAQ answer that there is no limit on commissions, plus recurring subscription commission.", "contact_access": "A named program contact email, maria@lumitylife.co.uk, is published in the FAQ for questions.", "opportunity_availability": "FAQ describes open sign-up and approval into the Referral Program with a dashboard and unique referral link.", "credibility": "Homepage presents clinically tested products and award-winning positioning for an established wellness brand."}'::jsonb);
