  insert into public.brands (name, website, description, country, status) values ('Bombas', 'https://bombas.com', 'Bombas is a U.S. comfort-focused sock and apparel brand that makes socks, underwear, t-shirts, slippers and shirts and donates one item for every item purchased. Its Ascend program page says over 200 million essential clothing items have been donated and counting. Its official affiliates page says it works with a network of over 3,500 giving partners across all 50 states.', 'United States', 'published') returning id into bid;
