  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@bombas.com', 'https://bombas.com/pages/affiliates', 'https://bombas.com/pages/affiliates', 'verified', now());
