  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bombas Affiliate Partner Program', 'https://www.ascendpartner.com/affiliate/registration?refid=142593', 'https://bombas.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bombas.com/pages/affiliates', 'official_site', 'affiliate', 'Official page: ''Join Bombas'' Affiliate Partner Program!'' FAQ: ''We offer 10% commission for every sale generated by a new customer & 1% commission for sales from existing customers. Not valid on gift cards.'' Joining is free via Ascend, PID #8171, applications reviewed in 3-5 business days. The phrase ''the opportunity to earn is endless'' refers to the product range, not an earnings cap — no ''no cap'' / ''unlimited earnings'' statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bombas.com/pages/affiliates', 'official_site', 'contact', 'Official page publishes: ''Feel free to reach out to affiliates@bombas.com'' for additional questions about the affiliate program or partnering with Bombas.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ascendpartner.com/affiliate/registration?refid=142593', 'listing', 'affiliate', 'Ascend / Partnerize registration page for the Bombas Socks Affiliate Program with an application form, repeating affiliates@bombas.com and the one-purchased, one-donated model.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 14, 14, 9, 5, '{"compensation": "Officially published 10% for new customers, reduced to 1% for existing customers, with no cap statement published.", "contact_access": "Dedicated official program page, a live application form, and a published affiliates@bombas.com email.", "credibility": "Mature U.S. brand with over 200 million items donated per its program page.", "niche_fit": "Everyday socks, underwear and apparel basics fit fashion and fitness creators well.", "opportunity_availability": "Free to join, applications reviewed within 3-5 business days per the official page.", "ugc_evidence": "The official program is built for partners promoting on personal social media or blogs, but no creator-count evidence was found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Muscle Nation', 'https://musclenation.org', 'Muscle Nation is a Brisbane, Australia activewear and supplements brand founded in August 2016, selling men''s and women''s activewear, protein powders, bars and nutritional supplements. It recently launched a new Affiliate Program for creators, with commission on sales, a personal discount link and access to an affiliate community.', 'AU', 'published') returning id into bid;
