  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://help.musclenation.org/en-US/become-an-affiliate-6081326', 'official_site', 'affiliate', 'Official Muscle Nation help page: ''We''ve recently launched our new Affiliate Program which is the best place for creators who are interested in partnering with us!'' Perks listed: commission on sales, a personal discount link to share with your audience, and access to the affiliate community; applications are reviewed and followed up by email.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/154693/muscle-nation-affiliate-program', 'listing', 'affiliate', 'Sovrn Commerce listing: ''Muscle Nation offers an 8% commission per sale through Sovrn Commerce'' with a 30-day cookie; joining is ''exclusively through Sovrn Commerce''. No cap / no-cap / unlimited-earnings wording appears anywhere on the page, so commission_cap is unknown, not uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/muscle-nation', 'listing', 'ugc_collab', 'Saturation evidence for ''low'': Beacons Universe (updated November 20, 2026) counts only 109 creators all time and only 3 sponsored posts mentioning Muscle Nation in the last 12 months, and the official help page describes the affiliate program as ''recently launched'' — a small, new program.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/muscle-nation/', 'listing', 'affiliate', 'Lasso independently lists the Muscle Nation affiliate program at 8% per sale with a 30-day cookie, corroborating the Sovrn rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 16, 12, 12, 8, 4, '{"compensation": "8% per sale is published on two listings, but no cap statement is published, so cap status is unknown.", "contact_access": "Dedicated official affiliate help page with an apply route; no published partnerships email.", "credibility": "Established since 2016, Brisbane-based with a 5,000 sqm warehouse and a Shopify case study.", "niche_fit": "Australian activewear plus supplements brand squarely in the fitness niche.", "opportunity_availability": "Program is described by the brand as recently launched and actively accepting creator applications.", "ugc_evidence": "109 Beacons creators and 370 brand-mention posts in 12 months, though only 3 were sponsored."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Manduka', 'https://www.manduka.com', 'Manduka is a premium yoga brand founded by yogi and architect Peter Sterios in 1997, known for eco-conscious, durable yoga mats, props, apparel and accessories. It partners with certified yoga and Pilates teachers, studios, retailers and wellness professionals through discount, affiliate, wholesale and co-branding programs.', 'United States', 'published') returning id into bid;
