  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.manduka.com/pages/lets-partner-manduka', 'official_site', 'affiliate', 'Official US Partner page (opened): ''PARTNER WITH MANDUKA... From wholesale purchasing and affiliate partnerships to co-branding opportunities'' and ''AFFILIATE PROGRAM — Share the Manduka products you love and earn comission on qualifying purchases.'' No rate or cap wording is stated on this page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://eu.manduka.com/pages/manduka-teacher-programs', 'official_site', 'affiliate', 'Official Manduka Teacher Community page (opened): Affiliate Program section states ''15% discount for your audience'' and ''10% commission on all qualifying sales you refer'' with an ''Apply for Affiliate Program'' link; FAQ requires a minimum 200-hour certification for yoga teachers. No cap / no-limit / unlimited-earnings wording is published, so commission_cap is unknown. No creator-count evidence was found, so saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://eu.manduka.com/pages/lets-partner-manduka', 'official_site', 'affiliate', 'Official partner page restates: ''Through this give back initiative, we''ll provide you directly 10% commission of your student''s or communities purchases on eu.manduka.com. Plus your student will receive an exclusive 15% at checkout.''', 'verified', now());
