  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 14, 12, 8, 5, '{"compensation": "Official 10% commission and 15% audience discount are published, but no cap statement is published so cap status is unknown.", "contact_access": "Dedicated official Partner page and Teacher Programs page with Apply links; no published partnerships email was found.", "credibility": "Established premium brand founded in 1997 with global retail and studio presence.", "niche_fit": "Premium yoga and movement brand directly in the fitness niche, gated to teachers and movement professionals.", "opportunity_availability": "Application is open online but eligibility requires active teaching and, for yoga teachers, 200-hour certification.", "ugc_evidence": "Official pages show teacher spotlights, collaborations, editorial features and community partnerships, but no sponsored-post counts were published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Varlo', 'https://www.varlo.com', 'Varlo is an endurance-sports apparel brand built for triathletes, cyclists and runners, selling triathlon suits, cycling bibs and training gear through its own store. It runs a creator-first partner program that pays commission on sales and a per-video bonus when creator content is picked for its ads.', null, 'published') returning id into bid;
