  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Varlo Creator Program', 'https://www.varlo.com/pages/creators', 'https://www.varlo.com/pages/creators', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.varlo.com/pages/creators', 'official_site', 'affiliate', 'Varlo''s official Creator Program page states: ''8% Commission on every sale'', a 30-day cookie window, commissions paid monthly, a personal discount code for followers, and ''$100 Per video picked for ads''. No cap wording (no ''no cap'' / ''unlimited earnings'') is published anywhere on the page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.varlo.com/pages/creators', 'official_site', 'ugc_collab', 'Saturation evidence for ''low'': the same official page headlines ''No follower minimum'' and ''0 Follower minimum'', tells applicants ''Small account? Perfect.'' and ''We don''t select creators based on follower count... not follower count'', and features only a handful of named athlete creators — a small program actively recruiting first-time and small-account creators.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 12, 10, 9, 3, '{"niche_fit": "Endurance apparel for triathletes, cyclists and runners \u2014 a focused fitness niche with strong gear-content fit.", "ugc_evidence": "A creator-first program with named athlete creators featured on the page and a $100 bonus when a creator video is picked for ads.", "compensation": "A published 8% commission plus the $100 per-video ad bonus, but no cap statement is published.", "contact_access": "A dedicated official creator page with an application route, but no published partnerships email.", "opportunity_availability": "Open application today with a zero follower minimum and monthly commission payouts.", "credibility": "Small independent endurance brand with limited independent coverage so far."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cuts Clothing', 'https://www.cutsclothing.com/', 'Cuts Clothing is a US premium men''s clothing brand specializing in T-shirts, polos, sweatshirts, bottoms and hats made with proprietary fabrics for work-leisure wear. It runs a CJ Affiliate program for publishers and creators and has run TikTok ambassador campaigns with micro-influencers through GRIN.', 'United States', 'published') returning id into bid;
