  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cuts Clothing Affiliate Program (CJ Affiliate)', null, 'https://linkclicky.com/affiliate-program/cuts-clothing/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/cuts-clothing/', 'listing', 'affiliate', 'LinkClicky program page (opened, last updated March 10, 2024): Website https://www.cutsclothing.com/, Affiliate Platform CJ Affiliate, Regions US, ''Commission: 10% per sale''; join step states ''You can join by visiting their website at Cuts Clothing Affiliate Program [signup.cj.com]''. No cap / no-limit wording is published, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/cuts-clothing-inc/', 'listing', 'affiliate', 'Conflicting published rate: Lasso lists Cuts Clothing, Inc. at 5% per sale with a 30-day cookie — rates should be verified in CJ at application. No cap statement in either listing.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://grin.co/case-studies/tik-tok-case-study-cuts-clothing/', 'listing', 'ugc_collab', 'GRIN case study: Cuts assigned ambassadors 1-2 TikTok videos per month, built ''a team of 15 micro influencers'' plus ''more than 20 three-month trial partnerships'' with influencers from 150,000 to over 5 million followers, targeting 20-30 pieces of content. This is UGC evidence but not a creator-count total for the affiliate program, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 11, 7, 7, 4, '{"compensation": "10% is published for the CJ program but a second listing publishes 5% and no cap statement exists, so compensation is scored mid-range.", "contact_access": "Join route is via CJ Affiliate as described by the listing; no published partnerships email or brand-owned program page was found.", "credibility": "Established DTC brand with athlete/influencer coverage and a GRIN case study, with rate inconsistency across listings.", "niche_fit": "Premium US men''s fashion brand in the assigned fashion category.", "opportunity_availability": "CJ Affiliate application is joinable for US publishers and creators, subject to approval.", "ugc_evidence": "GRIN documents a TikTok ambassador campaign with 15 micro-influencers and 20+ trial partnerships producing monthly video."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Barbell Jack', 'https://thebarbelljack.com', 'Barbell Jack sells a premium barbell jack gym accessory that makes loading and unloading weight plates faster and safer, used by home gyms, commercial facilities, physiotherapists and serious lifters. Its Partner Program is aimed at fitness influencers, coaches, gym owners and content creators.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://thebarbelljack.com/en-us/pages/register-affiliate-account', 'https://thebarbelljack.com/en-us/pages/register-affiliate-account', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://thebarbelljack.com/en-us/pages/register-affiliate-account.', 'https://thebarbelljack.com/en-us/pages/register-affiliate-account', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Barbell Jack Partner Program', 'https://thebarbelljack.com/en-us/pages/register-affiliate-account', 'https://thebarbelljack.com/en-us/pages/register-affiliate-account', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://thebarbelljack.com/en-us/pages/register-affiliate-account', 'official_site', 'affiliate', 'Barbell Jack''s official Partner Program page states verbatim: ''There is no cap on earnings'' and its FAQ answers ''How much commission can I earn?'' with ''there is no limit on how much you can earn'' — an explicit uncapped statement, so commission_cap is uncapped. The page does not publish an exact commission percentage (''Commission rates are competitive''), so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.loom.com/share/f56f7448f3a74fdcbbee7079bfdb6cbc', 'listing', 'affiliate', 'A Barbell Jack Partner Program welcome video published by the brand on Loom states partners receive a 40% discount on their orders, a 10% coupon code for followers, and ''earn a 30% commission on every referral''. This percentage is not published on the official program page, so it is recorded here as reported context only and commission_rate stays null.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://thebarbelljack.com/en-us/pages/register-affiliate-account', 'official_site', 'ugc_collab', 'The same official page says the program is for ''fitness influencers, gym owners, coaches, content creators, bloggers, and niche websites'', that ''No minimum audience size is required'', joining is free, and partners get ready-to-use banners, creative assets and real-time tracking. No creator counts are published anywhere fetched, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 10, 9, 9, 3, '{"niche_fit": "A single premium gym accessory for lifters \u2014 squarely fitness, though a narrower product than apparel.", "ugc_evidence": "A partner program explicitly built for fitness influencers and creators with banners and creative assets, but no published creator counts.", "compensation": "Commissions are explicitly uncapped on the brand''s own page, but no exact percentage is published there (a brand video reports 30%), so this stays mid-range.", "contact_access": "A dedicated official partner page with a registration route, but no published partnerships email.", "opportunity_availability": "Free to join with no minimum audience size and promotion starting immediately after approval.", "credibility": "Small single-product brand with limited independent coverage."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Rolla''s Jeans', 'https://rollasjeans.com', 'Rolla''s is a global denim brand born in Australia, built around clean lines, classic details, signature back-pocket stitching and vintage-inspired washes. It sells women''s and men''s jeans and apparel online at rollasjeans.com and runs an affiliate program for fashion bloggers and influencers.', 'Australia', 'published') returning id into bid;
