  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Rolla''s Jeans Affiliate Program via Rakuten LinkShare', 'https://getlasso.co/affiliate/rollas-jeans/', 'https://getlasso.co/affiliate/rollas-jeans/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/rollas-jeans/', 'listing', 'affiliate', 'Lasso lists the Rolla''s Jeans affiliate program for Fashion with ''Commission Rate: 5% Per Sale'' and a ''Join the Rolla''s Jeans affiliate program today'' link pointing to login.linkshare.com (Rakuten LinkShare). No cap wording (no ''no cap''/''unlimited earnings'') is published, so commission_cap is unknown; no creator counts are published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/rollasjeans-com-affiliate-program', 'listing', 'affiliate', 'Shopper.com lists ''Rolla''s Jeans APAC Affiliate Program - Get up to 5-10% payout per sale'' with instant approval through Shopper.com, corroborating a joinable program; the range conflicts with Lasso''s single 5% figure, so 5% is used as the primary rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rollasjeans.com/default/pages/our-story', 'official_site', 'general', 'Official Our Story page states: ''Rolla''s is a global denim brand that embodies the laid back personality, casual confidence and a love of classic jeans from where it was born - Australia.'' The brand''s official site blog also directs readers to tag ''@rollasjeans'' on socials.', 'verified', now());
