  insert into public.brands (name, website, description, country, status) values ('Reformation', 'https://www.thereformation.com', 'Reformation is a Los Angeles-based fashion brand founded in 2009 that makes sustainable women''s clothing and accessories, including dresses, denim, tops and shoes. It focuses on sustainable materials and tracking the environmental footprint of its clothing. Creator Hero reports it achieved revenues exceeding $350 million in 2023.', 'United States', 'published') returning id into bid;
