  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creator-hero.com/blog/reformation-affiliate-program-in-depth-review-pros-and-cons', 'listing', 'affiliate', 'States: ''Earn a 2.8% commission on each sale generated through your referral links'' with a 30-day cookie, and gives the sign-up URL https://www.thereformation.com/ref-affiliates.html. No cap wording (no ''no cap'' / ''unlimited earnings'') is published, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/reformation/', 'listing', 'affiliate', 'UpPromote lists the Reformation Affiliate Program for publishers, creators and influencers at ''Up to 2.8% on qualifying sales'', CPS, 30-day cookie, with unique referral links and banners. It notes networks such as CJ Affiliate or Rakuten Advertising may be used, so no single network is confirmed.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 10, 6, 8, 7, 5, '{"compensation": "A rate is published but it is low at 2.8% and no cap statement is published.", "contact_access": "A dedicated affiliate application page URL is published, but no partnerships email was found on a fetched page.", "credibility": "Founded in 2009 with reported 2023 revenue exceeding $350 million.", "niche_fit": "Premium sustainable women''s fashion is a strong fit for fashion creators.", "opportunity_availability": "An application route is published in two independent listings, though the official page itself was not directly fetched.", "ugc_evidence": "Listings describe the program as open to creators, influencers, TikTokers and YouTubers, but no UGC campaign counts were found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Glassons', 'https://www.glassons.com', 'Glassons is a women''s fashion retailer popular across Australia and New Zealand, offering affordable denim, swim, dresses, sweats and basics. Its official app listing describes it as ''the latest affordable women''s fashion'' and publishes its Instagram, TikTok and a general contact email.', 'Australia', 'published') returning id into bid;
