  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/glassons-com-affiliate-program', 'listing', 'affiliate', 'Shopper.com lists ''GLASSONS Affiliate Program - Get up to 3.19% payout per sale'' and states ''The GLASSONS affiliate program offers a payout rate of 3.19%'' with ''instant approval'' through Shopper.com. No cap wording (no ''no cap''/''unlimited earnings'') is published, so commission_cap is unknown; no creator counts are published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://reverbico.com/blog/affiliate-marketing-new-zealand/', 'listing', 'affiliate', 'Reverbico''s NZ affiliate guide lists Rakuten Advertising as ''Fashion brands | Glassons has run here'' and states ''Glassons: Women''s fashion through Rakuten, with a reported 4% for new customers and 2.5% for existing ones'' — a conflicting reported rate to Shopper''s 3.19%, so the Shopper figure is used as the primary listing rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://play.google.com/store/apps/details?id=com.glassons.customer.app&hl=en_IN', 'official_site', 'contact', 'Official Glassons app listing on Google Play states ''Contact us: Glassons.com, Instagram.com/glassons, tiktok.com/@glassons, help@glassons.com'' and describes ''the latest affordable women''s fashion from denim, swim, dresses, sweats, basics & much more.''', 'verified', now());
