  insert into public.brands (name, website, description, country, status) values ('Dissh', 'https://dissh.com.au', 'DISSH is a female-founded Australian fashion brand, described on its official FAQ as ''making effortless style an everyday habit.'' It sells women''s apparel online at dissh.com.au, with pants, camis, shirts, shorts, tops, jackets and knitwear among the products creators link on LTK.', 'Australia', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
