  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://company.shopltk.com/u/creator_blog_apply?hsCtaTracking=c61d613f-131d-4206-91bf-e9d4e659be82%7Cc3e8d142-a2bb-4103-8915-4ebc48e1751f', 'https://company.shopltk.com/u/creator_blog_apply?hsCtaTracking=c61d613f-131d-4206-91bf-e9d4e659be82%7Cc3e8d142-a2bb-4103-8915-4ebc48e1751f', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'LTK', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.shopltk.com/explore/itsgeorgialouise/posts/3024ba85-dfed-11f1-878c-c6bd9f9f741c.', 'https://company.shopltk.com/u/creator_blog_apply?hsCtaTracking=c61d613f-131d-4206-91bf-e9d4e659be82%7Cc3e8d142-a2bb-4103-8915-4ebc48e1751f', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'DISSH affiliate program via LTK Creator application', 'https://company.shopltk.com/u/creator_blog_apply?hsCtaTracking=c61d613f-131d-4206-91bf-e9d4e659be82%7Cc3e8d142-a2bb-4103-8915-4ebc48e1751f', 'https://www.dontpayfull.com/at/dissh.com.au', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.dontpayfull.com/at/dissh.com.au', 'listing', 'affiliate', 'DontPayFull states: ''Earn Commissions via LTK: If you''re a content creator, you can join the DISSH affiliate program through LTK. It''s a handy way to earn a commission on sales whenever you share your favourite pieces with your followers.'' No DISSH-specific rate and no cap wording (no ''no cap''/''unlimited'') is published, so commission_cap is unknown and creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopltk.com/explore/itsgeorgialouise/posts/3024ba85-dfed-11f1-878c-c6bd9f9f741c', 'listing', 'affiliate', 'Live LTK creator post ''My Dissh sale picks!'' (published 2026-11-14) lists a ''Shop this post / Paid links'' section with numerous products attributed directly to DISSH (e.g., ''SCOUT WHEAT POPLIN BARREL PANT | DISSH'', ''VANESSA BITTER CHOC GGT PANT | DISSH'') via on.ltk.com links, confirming DISSH products are commissionable through LTK.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dissh.com.au/pages/faq', 'official_site', 'general', 'Official DISSH FAQ page states: ''DISSH is a female-founded Australian fashion brand, making effortless style an everyday habit.'' No affiliate/ambassador page or partnerships email was found on the official site.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 4, 6, 7, 4, '{"compensation": "No DISSH-specific commission rate is published, so compensation cannot be scored highly.", "contact_access": "Joinable only via the LTK Creator application; no published DISSH partnerships email or program page.", "credibility": "Female-founded Australian brand with independent editorial coverage and a verified Instagram presence.", "niche_fit": "Established Australian women''s fashion brand with strong creator-style fit.", "opportunity_availability": "LTK application is open and DISSH products are actively linked by creators.", "ugc_evidence": "A live LTK post links many DISSH products as paid links, but no dedicated brand creator page was found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('CREGEN', 'https://cregenusa.com', 'US creatine supplement brand (the US arm of JeuDerm / NuDerma Group) selling creatine sachets in 30, 90 and 180-count packs, positioned around its CGG Amino-Bridge formula for performance, recovery and cognitive wellness audiences, sold direct through its own store with a wholesale program for gyms and clinics alongside the consumer affiliate program.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://cregenusa.com/affiliates.html', 'https://cregenusa.com/affiliates.html', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 15, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://cregenusa.com/affiliates.html.', 'https://cregenusa.com/affiliates.html', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'CREGEN Partner Program (Starter 15% / Pro 20%)', 'https://cregenusa.com/affiliates.html', 'https://cregenusa.com/affiliates.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cregenusa.com/affiliates.html', 'official_site', 'affiliate', 'CREGEN''s official Partner Program page (search-indexed text of the brand''s own affiliates page; a direct fetch was blocked by the site''s firewall) publishes two tiers: Starter pays 15% on the 30-sachet box (12% on the 90 pack, 10% on the 180 pack) and Pro pays 20% / 17% / 15%, and the Starter tier lists verbatim: ''Commission on subscription renewals, no cap'' — an explicit no-cap statement on the brand''s own program page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cregenusa.com/affiliates.html', 'official_site', 'ugc_collab', 'The same page says anyone with an engaged community aligned with performance, wellness, fitness or cognitive health can apply, applications are reviewed personally with most approved within 48 hours, there is no minimum sales requirement, and payouts are monthly by PayPal or ACH at a $50 minimum — a brand-new, small program structure.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cregenusa.com/wholesale.html', 'official_site', 'general', 'CREGEN''s official wholesale page prices the 30-count box at a $64.99 MSRP and offers gyms, fitness studios and clinics 40-48% wholesale discounts with dedicated account managers, showing an early-stage brand actively building every partner channel at once.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 17, 9, 9, 3, '{"niche_fit": "Creatine is one of the most content-friendly supplement categories on TikTok and YouTube, and CREGEN targets performance, recovery and cognitive-health communities directly.", "ugc_evidence": "A structured two-tier partner program with a personal code, monthly payouts and personal application review, explicitly recruiting community-led creators \u2014 but the program is new, so independent creator coverage is still thin.", "compensation": "Published 15% Starter rising to 20% Pro on the hero product, commission on subscription renewals, and an explicit ''no cap'' statement on the brand''s own page \u2014 the strongest compensation evidence in this group.", "contact_access": "A full application form on the official program page with a 48-hour personal review promise, but no published partnerships email.", "opportunity_availability": "Free to join today, no minimum sales, any approved partner can start at the Starter tier immediately.", "credibility": "New US brand backed by the JeuDerm / NuDerma group with a priced wholesale program, but a short consumer track record so far."}'::jsonb);
