  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 13, 8, 8, 5, '{"niche_fit": "Mushroom coffee alternatives and morning-ritual content are a core wellness UGC niche, and the brand recruits wellness creators by name.", "ugc_evidence": "Two distinct creator routes (publisher affiliate and social ambassador) with starter kits, bonuses and a partner community \u2014 mature, documented creator infrastructure.", "compensation": "10% per sale on the Impact affiliate program, and a flat $35 per new customer plus milestone bonuses on the ambassador route \u2014 solid, though no cap statement is published, so the cap stays unknown.", "contact_access": "Dedicated program pages with direct application links for both routes, but no published partnerships email.", "opportunity_availability": "Both programs are open to apply today, worldwide, across creator types from practitioners to artists.", "credibility": "Established, widely distributed coffee-alternative brand with years of national press and retail presence."}'::jsonb);
